encoding_algorithm.implementation:
function encode(index) {
  // Reversed letter sequences
  const letters = 'zyxwvutsrqponmlkjihgfedcbaZYXWVUTSRQPONMLKJIHGFEDCBA';
  const digits = '9876543210';

  if (index < 52) {
    return letters[index];
  } else if (index < 572) {
    const i = index - 52;
    return letters[Math.floor(i / 10)] + digits[i % 10];
  } else if (index < 3276) {
    const i = index - 572;
    return letters[Math.floor(i / 52)] + letters[i % 52];
  } else if (index < 8476) {
    const i = index - 3276;
    return letters[Math.floor(i / 100)] + digits[Math.floor((i % 100) / 10)] + digits[i % 10];
  } else {
    const i = index - 8476;
    let result = '';
    let n = i;
    do {
      result = letters[n % 52] + result;
      n = Math.floor(n / 52);
    } while (n >= 52);
    return letters[n] + result;
  }
}
